extern printf(fmt: string, ...);

# A simple function with no parameters, no return
frame sayHello() {
    printf("Hello from a function!\n");
}

# Function with parameters
frame greet(name: string) {
    printf("Hello, %s!\n", name);
}

# Function with return value
frame add(a: int, b: int) ret int {
    return a + b;
}

frame main() ret int {
    # Calling functions
    sayHello();

    greet("Alice");
    greet("Bob");

    local result: int = add(5, 3);
    printf("5 + 3 = %d\n", result);

    # Can use directly in expressions
    printf("10 + 20 = %d\n", add(10, 20));

    return 0;
}

extern printf(fmt: string, ...);

# Function with multiple parameters of different types
frame printPersonInfo(name: string, age: int, height: float) {
    printf("Name: %s\n", name);
    printf("Age: %d years\n", age);
    printf("Height: %.2f meters\n", height);
    printf("---\n");
}

# Math function with multiple parameters
frame calculateBMI(weight: float, height: float) ret float {
    # BMI = weight (kg) / height (m)^2
    return weight / (height * height);
}

frame main() ret int {
    printPersonInfo("Alice", 30, 1.65);
    printPersonInfo("Bob", 25, 1.80);

    local bmi: float = calculateBMI(70.0, 1.75);
    printf("BMI: %.1f\n", bmi);

    return 0;
}

