# Function that returns different values based on condition
frame absolute(n: int) ret int {
    if (n < 0) {
        return -n;  # Early return
    }
    return n;
}

# Function with multiple return points
frame grade(score: int) ret string {
    if (score >= 90) {
        return "A";
    }
    if (score >= 80) {
        return "B";
    }
    if (score >= 70) {
        return "C";
    }
    if (score >= 60) {
        return "D";
    }
    return "F";
}

# Boolean return
frame isAdult(age: int) ret bool {
    return age >= 18;
}

frame main() ret int {
    printf("Absolute of -5: %d\n", absolute(-5));
    printf("Absolute of 3: %d\n", absolute(3));

    printf("\nGrade for 85: %s\n", grade(85));
    printf("Grade for 72: %s\n", grade(72));
    printf("Grade for 55: %s\n", grade(55));

    printf("\nIs 20 an adult? %d\n", isAdult(20));
    printf("Is 15 an adult? %d\n", isAdult(15));

    return 0;
}

