# Global variable - accessible everywhere
global counter: int = 0;

frame incrementCounter() {
    counter = counter + 1;  # Can access global
}

frame printCounter() {
    printf("Counter: %d\n", counter);
}

frame demonstrateScope() {
    # Local variable - only exists in this function
    local x: int = 10;
    printf("Local x in demonstrateScope: %d\n", x);

    # This 'x' is different from any other 'x'
}

frame main() ret int {
    # Local variable in main
    local x: int = 5;
    printf("Local x in main: %d\n", x);

    demonstrateScope();  # Has its own 'x'

    printf("Local x in main (unchanged): %d\n", x);

    # Global variable demonstration
    printCounter();
    incrementCounter();
    incrementCounter();
    printCounter();

    return 0;
}

