# Return multiple values using a tuple
frame minMax(a: int, b: int, c: int) ret (int, int) {
    local min: int = a;
    local max: int = a;

    if (b < min) { min = b; }
    if (c < min) { min = c; }

    if (b > max) { max = b; }
    if (c > max) { max = c; }

    return (min, max);  # Return a tuple
}

# Divide and get quotient + remainder
frame divMod(dividend: int, divisor: int) ret (int, int) {
    local quotient: int = dividend / divisor;
    local remainder: int = dividend % divisor;
    return (quotient, remainder);
}

frame main() ret int {
    # Destructure tuple return value (type each variable inline)
    local (min: int, max: int) = minMax(5, 2, 8);
    printf("Min: %d, Max: %d\n", min, max);

    local (q: int, r: int) = divMod(17, 5);
    printf("17 / 5 = %d remainder %d\n", q, r);

    return 0;
}

