extern printf(fmt: string, ...);

frame power(base: int, exp: int) ret int {
    if (exp == 0) {
        return 1;
    }

    local result: int = 1;
    loop (local i: int = 0; i < exp; i = i + 1) {
        result = result * base;
    }
    return result;
}

frame main() ret int {
    printf("2^0 = %d\n", power(2, 0));
    printf("2^10 = %d\n", power(2, 10));
    printf("3^4 = %d\n", power(3, 4));

    return 0;
}
